function computeKpi(staff:AnyRecord[],tasks:AnyRecord[],checks:AnyRecord[],violations:AnyRecord[],rules:AnyRecord[]){return staff.map(s=>{const st=tasks.filter(x=>same(x.assignee,s.name));const sc=checks.filter(x=>same(x.person,s.name));const sv=violations.filter(x=>same(x.person,s.name));let taskScore=0;const details:string[]=[];for(const x of st){const key=text(x.evalStatus).toUpperCase();const value=Number(TASK_SCORE[key]??0);taskScore+=value;if(value)details.push(`${value>0?'+':''}${value} Giao việc: ${x.title} (${key})`);}const checklistScore=sc.reduce((n,x)=>n+num(x.kpi),0);for(const x of sc){if(num(x.kpi))details.push(`${x.kpi} Bảng kiểm ${x.date}: ${x.rate}%`);}const violationScore=-sv.reduce((n,x)=>n+Math.abs(num(x.points)),0);for(const x of sv){if(num(x.points))details.push(`-${Math.abs(num(x.points))} Vi phạm ${x.date}: ${x.errorName}`);}const total=100+taskScore+checklistScore+violationScore;const rank=rankFor(total,rules);return {staffId:s.id,name:s.name,person:s.name,department:s.department,position:s.position,base:100,taskScore,checklistScore,violationScore,total,ranking:rank.ranking,rank:rank.ranking,rankingColor:rank.color,details,taskCount:st.length,checkCount:sc.length,violationCount:sv.length};});}

