function buildChecklistParity(f:Filters,staff:AnyRecord[],departments:string[]){return Promise.all([readSheet(S.checklists),readSheet(S.checklistForms),readSheet(S.checklistCriteria),readSheet(S.checklistDetails),readSheet(S.checklistConfig)]).then(([historyRows,formRows,criterionRows,detailRows,configRows])=>{const configs=configRows.map(checklistConfig).filter(Boolean) as AnyRecord[];const all=historyRows.map(x=>checklistParityRow(x,configs));const rows=all.filter(x=>inRange(x.date,f)&&(!f.department||same(x.department,f.department))&&(!f.person||same(x.person,f.person))&&(!f.formCode||same(x.formCode,f.formCode)));const forms=all;const masterForms=formRows.map(formMaster);const criteria=criterionRows.map(criterion);const formMap=all.map(x=>x as AnyRecord);const selected=new Set(rows.map(x=>String(x.id)));const details=detailRows.map(x=>checklistDetail(x,formMap)).filter(x=>selected.has(String(x.formId)));const summary={total:rows.length,applied:rows.reduce((n,x)=>n+num(x.applied),0),pass:rows.reduce((n,x)=>n+num(x.pass),0),fail:rows.reduce((n,x)=>n+num(x.fail),0),na:rows.reduce((n,x)=>n+num(x.na),0),averageRate:rows.length?Math.round(rows.reduce((n,x)=>n+num(x.rate),0)/rows.length*100)/100:0,averagePercentRate:rows.length?Math.round(rows.reduce((n,x)=>n+num(x.percentRate),0)/rows.length*100)/100:0};return {rows,total:rows.length,forms:masterForms,criteria,details,historyDetails:details,percentConfig:configs,scoring:configs,staff,departments,summary,options:{formCodes:masterForms.map(x=>x.code),results:['ĐẠT','KHÔNG ĐẠT','KHÔNG ÁP DỤNG'],statuses:['Hoạt động','Tạm ngưng']}};});}
